1	import {
2	  closeSync,
3	  existsSync,
4	  mkdirSync,
5	  mkdtempSync,
6	  openSync,
7	  readFileSync,
8	  readdirSync,
9	  realpathSync,
10	  rmSync,
11	  statSync,
12	  watch,
13	  writeFileSync,
14	} from 'node:fs';
15	import { createHash } from 'node:crypto';
16	import { tmpdir } from 'node:os';
17	import { isAbsolute, join, relative, resolve } from 'node:path';
18	import { afterEach, beforeEach, describe, expect, it, onTestFinished, vi } from 'vitest';
19	import type { WorkingDirectorySpec } from '@graphgoblin/contracts';
20	import { TemplateError } from '@graphgoblin/domain';
21	import { createTestEngine, singleNodeLoop } from '@graphgoblin/engine/testing';
22	import { FsArtifactStore } from './artifacts.js';
23	import { FsWorkspace } from './workspace.js';
24	import {
25	  OwnedRunResources,
26	  type OwnedRunResource,
27	  type RunResourceJournal,
28	} from './owned-resources.js';
29	
30	let dataDir: string;
31	
32	beforeEach(() => {
33	  dataDir = mkdtempSync(join(tmpdir(), 'gg-wp-e3-'));
34	});
35	
36	afterEach(() => {
37	  rmSync(dataDir, { recursive: true, force: true });
38	});
39	
40	function createRelativeWorkspaceTarget(): string {
41	  const fixtureDir = mkdtempSync(join(process.cwd(), 'gg-wp-relative-'));
42	  onTestFinished(() => rmSync(fixtureDir, { recursive: true, force: true }));
43	  return join(fixtureDir, 'workspace');
44	}
45	
46	describe('FsWorkspace', () => {
47	  it('resolves fixed, relative, and temporary directories and reuses them', async () => {
48	    const ws = new FsWorkspace(dataDir);
49	    const fixed = await ws.resolve({ kind: 'fixed', path: join(dataDir, 'fixed') }, 'run1');
50	    expect(statSync(fixed).isDirectory()).toBe(true);
51	    expect(await ws.resolve({ kind: 'fixed', path: fixed }, 'run2')).toBe(fixed);
52	    const relativePath = relative(process.cwd(), createRelativeWorkspaceTarget());
53	    expect(isAbsolute(relativePath)).toBe(false);
54	    const relativeDirectory = await ws.resolve({ kind: 'fixed', path: relativePath }, 'run1');
55	    expect(relativeDirectory).toBe(resolve(relativePath));
56	    expect(statSync(relativeDirectory).isDirectory()).toBe(true);
57	    const temp = await ws.resolve({ kind: 'temp' }, 'run1');
58	    expect(temp).toBe(join(dataDir, 'workspaces', 'run1'));
59	    expect(statSync(temp).isDirectory()).toBe(true);
60	    expect(await ws.resolve({ kind: 'temp' }, 'run1')).toBe(temp);
61	  });
62	
63	  it('writes relative and absolute files, creating parent directories', async () => {
64	    const ws = new FsWorkspace(dataDir);
65	    const dir = await ws.resolve({ kind: 'temp' }, 'run2');
66	    const rel = await ws.writeFile(dir, 'out/nested/result.json', '{"a":1}');
67	    expect(rel).toBe(join(dir, 'out', 'nested', 'result.json'));
68	    expect(readFileSync(rel, 'utf8')).toBe('{"a":1}');
69	    const absTarget = join(dataDir, 'elsewhere', 'file.txt');
70	    const abs = await ws.writeFile(dir, absTarget, 'hi');
71	    expect(isAbsolute(abs)).toBe(true);
72	    expect(readFileSync(absTarget, 'utf8')).toBe('hi');
73	  });
74	
75	  it('propagates mkdir failures and succeeds after the external path is repaired', async () => {
76	    const blocker = join(dataDir, 'blocker');
77	    writeFileSync(blocker, 'blocks a directory');
78	    const ws = new FsWorkspace(dataDir);
79	    const spec = { kind: 'fixed', path: join(blocker, 'child') } as const;
80	    await expect(ws.resolve(spec, 'run')).rejects.toThrow();
81	    expect(readFileSync(blocker, 'utf8')).toBe('blocks a directory');
82	    rmSync(blocker);
83	    expect(await ws.resolve(spec, 'run')).toBe(spec.path);
84	    expect(statSync(spec.path).isDirectory()).toBe(true);
85	  });
86	});
87	
88	describe('engine workspace filesystem boundary', () => {
89	  // RunManager and the workspace are real; script execution and the journal are controlled ports.
90	  it.each(['fixed', 'relative', 'temp', 'template'] as const)(
91	    'uses real %s paths, caches resolution for delivery, and claims only new temporary directories',
92	    async (kind) => {
93	      const target =
94	        kind === 'relative' ? createRelativeWorkspaceTarget() : join(dataDir, 'user-owned');
95	      const fixedPath = kind === 'relative' ? relative(process.cwd(), target) : target;
96	      if (kind === 'relative') expect(isAbsolute(fixedPath)).toBe(false);
97	      const claims: OwnedRunResource[] = [];
98	      const journal: RunResourceJournal = {
99	        find: () => Promise.resolve(undefined),
100	        claim: vi.fn((resource) => {
101	          claims.push(resource);
102	          return Promise.resolve();
103	        }),
104	        use: vi.fn(() => Promise.resolve()),
105	      };
106	      const resources = new OwnedRunResources(dataDir, journal);
107	      const engine = await createTestEngine();
108	      const port = vi
109	        .spyOn(engine.ports.workspace, 'resolve')
110	        .mockImplementation(resources.workspace.resolve);
111	      vi.spyOn(engine.ports.workspace, 'writeFile').mockImplementation(
112	        resources.workspace.writeFile,
113	      );
114	      const spec: WorkingDirectorySpec =
115	        kind === 'temp'
116	          ? { kind: 'temp' }
117	          : kind === 'template'
118	            ? { kind: 'template', template: '\t {{trigger.payload.path}}\r\n' }
119	            : { kind: 'fixed', path: fixedPath };
120	      const loop = singleNodeLoop(
121	        `real workspace ${kind}`,
122	        {
123	          id: 'script',
124	          kind: 'script',
125	          label: 'Script',
126	          config: { command: 'controlled-script', cwd: 'workspace' },
127	        },
128	        {
129	          returns: '"real file bytes"',
130	          destinations: [{ kind: 'file', path: 'nested/result.txt', format: 'text' }],
131	        },
132	      );
133	      loop.settings = { workingDirectory: spec };
134	      try {
135	        const run = await engine.runToIdle(engine.publish(loop).loopId, { path: target });
136	        const path = kind === 'temp' ? join(realpathSync(dataDir), 'workspaces', run.id) : target;
137	        expect(run.status).toBe('succeeded');
138	        expect(port).toHaveBeenCalledTimes(1);
139	        expect(port).toHaveBeenCalledWith(
140	          kind === 'temp' ? { kind: 'temp' } : { kind: 'fixed', path: fixedPath },
141	          run.id,
142	        );
143	        expect(engine.ports.scripts.calls[0]?.cwd).toBe(path);
144	        expect(readFileSync(join(path, 'nested/result.txt'), 'utf8')).toBe('real file bytes');
145	        const actual = realpathSync(path);
146	        const canonical = process.platform === 'win32' ? actual.toLowerCase() : actual;
147	        expect(journal.use).toHaveBeenCalledExactlyOnceWith(
148	          run.id,
149	          `workspace:${canonical}`,
150	          canonical,
151	        );
152	        expect(claims).toHaveLength(kind === 'temp' ? 1 : 0);
153	        if (kind === 'temp') {
154	          expect(claims[0]).toMatchObject({ ownerRunId: run.id, kind: 'workspace', path });
155	          expect(claims[0]?.identity).toEqual(expect.any(String));
156	          expect(await resources.workspace.resolve({ kind: 'temp' }, run.id)).toBe(path);
157	          expect(claims).toHaveLength(1);
158	        }
159	      } finally {
160	        engine.manager.stop();
161	      }
162	    },
163	  );
164	
165	  it.each([
166	    '\t {{vars.missing}}\n',
167	    'private-marker\n{% invalid_private %}',
168	    '{% include "private-marker" %}',
169	  ])(
170	    'rejects an invalid engine template with zero resolve, mkdir and journal effects (%#)',
171	    async (template) => {
172	      const journal: RunResourceJournal = {
173	        find: vi.fn(() => Promise.resolve(undefined)),
174	        claim: vi.fn(() => Promise.resolve()),
175	        use: vi.fn(() => Promise.resolve()),
176	      };
177	      const resources = new OwnedRunResources(dataDir, journal);
178	      const engine = await createTestEngine();
179	      const port = vi
180	        .spyOn(engine.ports.workspace, 'resolve')
181	        .mockImplementation(resources.workspace.resolve);
182	      const loop = singleNodeLoop('reject before fs', {
183	        id: 'script',
184	        kind: 'script',
185	        label: 'Script',
186	        config: { command: 'controlled-script', cwd: 'workspace' },
187	      });
188	      loop.settings = { workingDirectory: { kind: 'template', template } };
189	      try {
190	        const run = await engine.runToIdle(engine.publish(loop).loopId);
191	        expect(run.failure).toMatchObject({
192	          code: 'TEMPLATE_ERROR',
193	          nodeId: 'script',
194	          resumable: false,
195	          details: { boundary: 'settings.workingDirectory.template' },
196	        });
197	        await expect(engine.manager.resume(run.id)).rejects.toMatchObject({
198	          code: 'FAILURE_NOT_RESUMABLE',
199	        });
200	        expect(port).not.toHaveBeenCalled();
201	        expect(engine.ports.scripts.calls).toEqual([]);
202	        expect(readdirSync(dataDir)).toEqual([]);
203	        expect(journal.claim).not.toHaveBeenCalled();
204	        expect(journal.use).not.toHaveBeenCalled();
205	        expect(journal.find).not.toHaveBeenCalled();
206	      } finally {
207	        engine.manager.stop();
208	      }
209	    },
210	  );
211	
212	  it('keeps a journal rejection external after mkdir and does not cache the failed resolution', async () => {
213	    const fault = new TemplateError('private-journal-marker');
214	    const journal: RunResourceJournal = {
215	      find: () => Promise.resolve(undefined),
216	      claim: vi.fn(() => Promise.resolve()),
217	      use: vi.fn(() => Promise.resolve()).mockRejectedValueOnce(fault),
218	    };
219	    const resources = new OwnedRunResources(dataDir, journal);
220	    const engine = await createTestEngine();
221	    const port = vi
222	      .spyOn(engine.ports.workspace, 'resolve')
223	      .mockImplementation(resources.workspace.resolve);
224	    const loop = singleNodeLoop('journal repair', {
225	      id: 'script',
226	      kind: 'script',
227	      label: 'Script',
228	      config: { command: 'controlled-script', cwd: 'workspace' },
229	    });
230	    const target = join(dataDir, 'created-before-journal-fault');
231	    loop.settings = {
232	      workingDirectory: { kind: 'template', template: ' {{trigger.payload.path}} ' },
233	    };
234	    try {
235	      const run = await engine.runToIdle(engine.publish(loop).loopId, { path: target });
236	      expect(run.failure).toMatchObject({
237	        code: 'INTERNAL_ERROR',
238	        nodeId: 'script',
239	        resumable: true,
240	      });
241	      expect(JSON.stringify(run.failure)).not.toContain('private-journal-marker');
242	      expect(run.failure?.details).toBeUndefined();
243	      expect(existsSync(target)).toBe(true);
244	      expect(engine.ports.scripts.calls).toEqual([]);
245	      expect(journal.claim).not.toHaveBeenCalled();
246	      await engine.manager.resume(run.id);
247	      expect((await engine.settle(run.id)).status).toBe('succeeded');
248	      expect(port).toHaveBeenCalledTimes(2);
249	      expect(journal.use).toHaveBeenCalledTimes(2);
250	      expect(engine.ports.scripts.calls[0]?.cwd).toBe(target);
251	    } finally {
252	      engine.manager.stop();
253	    }
254	  });
255	});
256	
257	describe('FsArtifactStore', () => {
258	  // POSIX permits replacement while the destination is open; this exercises Windows sharing.
259	  it.skipIf(process.platform !== 'win32')(
260	    'accepts verified bytes published by another writer while a read handle blocks replacement',
261	    async () => {
262	      const content = 'x'.repeat(32 * 1024 * 1024);
263	      const bytes = Buffer.from(content);
264	      const hash = createHash('sha256').update(bytes).digest('hex');
265	      const ref = `artifact:transcript/${hash}`;
266	      const dir = join(dataDir, 'artifacts', 'transcript');
267	      const final = join(dir, hash);
268	      mkdirSync(dir, { recursive: true });
269	      let readHandle: number | undefined;
270	      let injected = false;
271	      let setupError: unknown;
272	      const observer = watch(dir, (_event, name) => {
273	        if (injected || !name?.startsWith(`.${hash}.`) || !name.endsWith('.tmp')) return;
274	        injected = true;
275	        try {
276	          // A .tmp proves put already checked the missing destination. Synchronous setup keeps
277	          // this callback ahead of put's remaining asynchronous write/fsync/rename continuations.
278	          statSync(join(dir, name));
279	          writeFileSync(final, bytes);
280	          readHandle = openSync(final, 'r');
281	        } catch (error) {
282	          setupError = error;
283	        }
284	      });
285	      const store = new FsArtifactStore(dataDir);
286	      try {
287	        await expect(store.put('transcript', content)).resolves.toEqual({
288	          ref,
289	          bytes: bytes.length,
290	        });
291	        expect(injected).toBe(true);
292	        expect(setupError).toBeUndefined();
293	        expect(readHandle).toBeDefined();
294	        expect(await store.get(ref)).toBe(content);
295	        expect(readFileSync(final).equals(bytes)).toBe(true);
296	        expect(readdirSync(dir)).toEqual([hash]);
297	      } finally {
298	        observer.close();
299	        if (readHandle !== undefined) closeSync(readHandle);
300	      }
301	    },
302	  );
303	
304	  it('rejects corrupted final bytes and atomically repairs a pre-existing partial file', async () => {
305	    const store = new FsArtifactStore(dataDir);
306	    const content = 'complete transcript: 世界 🧙';
307	    const hash = createHash('sha256').update(content).digest('hex');
308	    const dir = join(dataDir, 'artifacts', 'transcript');
309	    mkdirSync(dir, { recursive: true });
310	    writeFileSync(join(dir, hash), 'complete');
311	    const ref = `artifact:transcript/${hash}`;
312	    await expect(store.get(ref)).rejects.toMatchObject({ code: 'ARTIFACT_CORRUPT', ref });
313	    const repaired = await store.put('transcript', content);
314	    expect(repaired.ref).toBe(ref);
315	    expect(readFileSync(join(dir, hash)).equals(Buffer.from(content))).toBe(true);
316	    expect(await store.get(ref)).toBe(content);
317	    expect(readdirSync(dir)).toEqual([hash]);
318	  });
319	
320	  it('does not accept truncated bytes on a repeated put', async () => {
321	    const store = new FsArtifactStore(dataDir);
322	    const { ref } = await store.put('transcript', 'a complete transcript');
323	    const hash = ref.split('/')[1]!;
324	    writeFileSync(join(dataDir, 'artifacts', 'transcript', hash), 'a');
325	    expect(await store.put('transcript', 'a complete transcript')).toMatchObject({ ref });
326	    expect(await store.get(ref)).toBe('a complete transcript');
327	  });
328	
329	  it('ignores interrupted temporary writes and converges under identical and different concurrent puts', async () => {
330	    const store = new FsArtifactStore(dataDir);
331	    const dir = join(dataDir, 'artifacts', 'transcript');
332	    mkdirSync(dir, { recursive: true });
333	    writeFileSync(join(dir, '.interrupted.tmp'), 'partial');
334	    const contents = ['', '世界 🧙\u0000\r\n'.repeat(200_000), 'other content'];
335	    const stored = await Promise.all(
336	      contents.flatMap((content) => [
337	        store.put('transcript', content),
338	        new FsArtifactStore(dataDir).put('transcript', content),
339	      ]),
340	    );
341	    for (const [i, content] of contents.entries()) {
342	      const a = stored[i * 2]!;
343	      expect(stored[i * 2 + 1]).toEqual(a);
344	      expect(a.bytes).toBe(Buffer.byteLength(content));
345	      expect(await store.get(a.ref)).toBe(content);
346	      expect(await store.get(a.ref.toUpperCase())).toBeUndefined();
347	      expect(readFileSync(join(dir, a.ref.split('/')[1]!)).equals(Buffer.from(content))).toBe(true);
348	    }
349	    expect(new Set(stored.map((item) => item.ref)).size).toBe(contents.length);
350	    expect(readdirSync(dir).sort()).toEqual(
