68	const canonical = (path: string) =>
69	  process.platform === 'win32' ? resolve(path).toLowerCase() : resolve(path);
70	const identity = (stat: Awaited<ReturnType<typeof info>>) =>
71	  JSON.stringify([String(stat.dev), String(stat.ino), String(stat.birthtimeNs)]);
72	const info = (path: string) => lstat(path, { bigint: true });
73	async function exists(path: string) {
74	  try {
75	    return await info(path);
76	  } catch (error) {
77	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined;
78	    throw error;
79	  }
80	}
