82	/** One process holds the data-directory lock. This gate also excludes publication during reaping. */
83	export class OwnedRunResources {
84	  private readonly gate = new Mutex();
85	  private physicalRoot?: Promise<string>;
86	  readonly workspace: WorkspacePort;
87	  readonly artifacts: ArtifactStorePort;
88	  constructor(
89	    private readonly dataDir: string,
90	    private readonly journal: RunResourceJournal,
91	  ) {
92	    const workspace = new FsWorkspace(dataDir);
93	    const artifactStore = async () => new FsArtifactStore(await this.physicalDataDir());
94	    this.workspace = {
95	      resolve: (spec, runId) =>
96	        this.exclusive(async () => {
97	          let path: string;
98	          if (spec.kind === 'temp') {
99	            const root = await this.directory('workspaces');
100	            path = join(root, runId);
101	            if (dirname(path) !== root) throw new Error('Invalid workspace identity');
102	            let created = false;
103	            try {
104	              await mkdir(path);
105	              created = true;
106	            } catch (error) {
107	              if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;
108	            }
109	            if (!created) await new FsWorkspace(await this.physicalDataDir()).resolve(spec, runId);
110	            if (created)
111	              await this.journal.claim({
112	                key: `workspace:${canonical(path)}`,
113	                ownerRunId: runId,
114	                kind: 'workspace',
115	                path,
116	                identity: identity(await info(path)),
117	              });
118	          } else path = await workspace.resolve(spec, runId);
119	          // Record canonical use even for a user-owned/shared directory, without claiming it.
120	          const actual = await realpath(path);
121	          await this.journal.use(runId, `workspace:${canonical(actual)}`, canonical(actual));
122	          return path;
123	        }),
124	      writeFile: (dir, path, content) => workspace.writeFile(dir, path, content),
