  const out = fs.openSync(stdoutPath, 'wx');
  const err = fs.openSync(stderrPath, 'wx');
  const watchers = watch.map(({ label, dir, filter }) => {
    const logPath = path.join(RAW, `${id}.watch-${label}.jsonl`);
