const envValue = (name) => {
  const key = Object.keys(process.env).find((k) => k.toUpperCase() === name);
  return key ? process.env[key] : undefined;
};
function childEnv(temp, extra = {}) {
  const override = {
    PATH: NODE_DIR + ';' + envValue('PATH'),
    TEMP: temp,
    TMP: temp,
