const ENV_KEYS = [
  'TEMP',
  'TMP',
  'NODE_COMPILE_CACHE',
  'NODE_OPTIONS',
  'QA_D215_LOG',
  'QA_D215_FIXTURE',
  'QA_D215_TAP',
  'QA_D215_OLD_CONTROL',
  'QA_D215_WORKER_TEMP',
  'GIT_OPTIONAL_LOCKS',
  'PNPM_DISABLE_SELF_UPDATE_CHECK',
  'TURBO_TELEMETRY_DISABLED',
  'npm_config_update_notifier',
  'NO_COLOR',
