  fs.closeSync(err);
  const rec = {
    id,
    command,
    cwd,
    started,
    ended: now(),
    exitCode,
    signal,
    spawnError,
    timedOut,
    timeoutMs,
    env: envSubset(env),
    stdout: record(stdoutPath),
    stderr: record(stderrPath),
    watchers: watchers.map(({ label, dir, logPath }) => ({ label, dir, log: record(logPath) })),
