  return childEnv(temp, {
    NODE_OPTIONS: `--require=${OBSERVER.replaceAll('\\', '/')}`,
    QA_D215_LOG: log,
    QA_D215_FIXTURE: FIXTURE,
    QA_D215_TAP: tap ? '1' : '0',
    ...(oldControl ? { QA_D215_OLD_CONTROL: '1' } : {}),
    ...(workerTemp ? { QA_D215_WORKER_TEMP: workerTemp } : {}),
  });
}
